         string tavernAssets = Path.Combine(root, "Content/WorldGeneration/VillageTavern");
         string villageMap = Path.Combine(assets, "AbandonedVillage/L_AbandonedVillage.umap");
         string[] bakedHills = { "FixedLayout/Hills.layout", "FixedLayout/Quarry.dressing", "FixedTerrain/Hills.terrain" };
+        string region = Path.Combine(root, "Content/ForestPathStudy/VillageRegion");
+        string[] forestPackages = { "Content/GameMaps/L_ForestPathVillage.umap",
