+            "Content/ForestPathStudy/VillageRegion/Quarry/L_ForestQuarry.umap",
+            "Content/EuropeanHornbeam/Geometry/SimpleWind/SM_EuropeanHornbeam_Forest_04.uasset",
+            "Content/EuropeanHornbeam/Geometry/SimpleWind/SM_EuropeanHornbeam_Forest_05.uasset" };
+        string[] forestFolders = { "Reference/Terrain", "Themes", "Ecology" };
         var inputs = Directory.GetFiles(generation, "Temperate*", SearchOption.TopDirectoryOnly)
+            .Concat(Directory.GetFiles(generation, "Forest*", SearchOption.TopDirectoryOnly))
             .Where(p => (p.EndsWith(".h") || p.EndsWith(".cpp") || p.EndsWith(".inl")) &&
                 !Path.GetFileName(p).Contains("Capture") && !Path.GetFileName(p).Contains("Compatibility"))
             .Concat(Directory.Exists(assets) ? Directory.GetFiles(assets, "*.uasset", SearchOption.AllDirectories) : Array.Empty<string>())
@@ -97,6 +106,11 @@
             .Concat(Directory.Exists(tavernAssets) ? Directory.GetFiles(tavernAssets, "SM_*.uasset", SearchOption.AllDirectories) : Array.Empty<string>())
             .Concat(File.Exists(villageMap) ? new[] { villageMap } : Array.Empty<string>())
             .Concat(bakedHills.Select(file => Path.Combine(assets, file)))
+            .Concat(forestPackages.Select(file => Path.Combine(root, file)))
+            .Concat(new[] { "ChapelNavigationGeometry.h", "ChapelNavigationGeometry.cpp" }.Select(file => Path.Combine(generation,file)))
+            .Concat(forestFolders.SelectMany(folder => Directory.Exists(Path.Combine(region, folder))
